package io.github.hienpham0344.stayfinder.media.service;import org.springframework.stereotype.Component;import org.springframework.scheduling.annotation.Scheduled;import org.springframework.beans.factory.annotation.Value;
@Component public class MediaCleanupWorker{private final MediaService service;private final boolean enabled;public MediaCleanupWorker(MediaService service,@Value("${stayfinder.workers.enabled:true}")boolean enabled){this.service=service;this.enabled=enabled;}@Scheduled(fixedDelay=3600000)public void run(){if(enabled)try{service.cleanup();service.cleanupOrphanFiles();}catch(RuntimeException e){org.slf4j.LoggerFactory.getLogger(getClass()).warn("Media cleanup failed: {}",e.getClass().getSimpleName());}}}
